1000→        command: "parent-ci-cmd"
1001→        env:
1002→          PARENT_VAR: "from-parent"
1003→"#;
1004→
1005→        server.mock(|when, then| {
1006→            when.method(GET).path("/parent.yml");
1007→            then.status(200).body(parent_yaml);
1008→        });
1009→
1010→        // Child config as YAML that extends parent and overrides the ci block
1011→        let child_yaml = format!(
1012→            r#"
1013→extends:
1014→  - url: {}
1015→app_name: ChildApp
1016→steps:
1017→  setup:
1018→    environments:
1019→      ci:
1020→        command: "child-ci-cmd"
1021→"#,
1022→            server.url("/parent.yml")
1023→        );
1024→
1025→        let child_config: BivvyConfig = serde_yaml::from_str(&child_yaml).unwrap();
1026→
1027→        let resolver = resolver_with_mock(&server);
1028→        let resolved = resolver.resolve(&child_config).unwrap();
1029→
1030→        // Child's app_name wins
1031→        assert_eq!(resolved.app_name, Some("ChildApp".to_string()));
1032→
1033→        // The ci environment block should be fully replaced by child
