  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }
101→
102→    fn fetch_remote(&self, url: &str) -> Result<String> {
103→        let response = self
104→            .client
105→            .get(url)
106→            .send()
107→            .with_context(|| format!("Failed to fetch {}", url))?;
108→
109→        if !response.status().is_success() {
110→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
111→        }
112→
113→        response
114→            .text()
115→            .with_context(|| format!("Failed to read response from {}", url))
116→    }
117→
118→    fn check_cache(&self, url: &str) -> Result<Option<String>> {
119→        let cache_path = self.cache_path(url);
120→        if cache_path.exists() {
121→            let content = std::fs::read_to_string(&cache_path)?;
122→            Ok(Some(content))
123→        } else {
124→            Ok(None)
125→        }
126→    }
127→
128→    fn save_cache(&self, url: &str, content: &str) -> Result<()> {
129→        let cache_path = self.cache_path(url);
130→        if let Some(parent) = cache_path.parent() {
131→            std::fs::create_dir_all(parent)?;
132→        }
133→        std::fs::write(&cache_path, content)?;
134→        Ok(())
135→    }
136→
137→    fn cache_path(&self, url: &str) -> PathBuf {
138→        use sha2::{Digest, Sha256};
139→        let mut hasher = Sha256::new();
140→        hasher.update(url.as_bytes());
141→        let hash = hex::encode(hasher.finalize());
142→        self.cache_dir.join(format!("{}.yml", hash))
143→    }
144→
145→    /// Clear the cache for a specific URL.
146→    pub fn clear_cache(&self, url: &str) -> Result<()> {
147→        let cache_path = self.cache_path(url);
148→        if cache_path.exists() {
149→            std::fs::remove_file(&cache_path)?;
150→        }

  1→//! Variable interpolation for configuration values.
  2→//!
  3→//! Bivvy supports variable interpolation in config values using `${variable}` syntax.
  4→//!
  5→//! # Syntax
  6→//!
  7→//! - `${variable_name}` - replaced with variable value
  8→//! - `$${escaped}` - produces literal `${escaped}` in output
  9→//!
 10→//! # Example
 11→//!
 12→//! ```yaml
 13→//! command: "echo Hello, ${name}!"
 14→//! # With name="World", produces: echo Hello, World!
 15→//! ```
 16→
 17→use crate::error::{BivvyError, Result};
 18→use std::collections::{HashMap, HashSet};
 19→
 20→/// A segment of an interpolated string.
 21→#[derive(Debug, Clone, PartialEq)]
 22→pub enum Segment {
 23→    /// Literal text
 24→    Literal(String),
 25→    /// Variable reference: ${name}
 26→    Variable(String),
 27→}
 28→
 29→/// Parse a string containing ${var} interpolations.
 30→///
 31→/// Supports:
 32→/// - `${variable_name}` - variable interpolation
 33→/// - `$${escaped}` - literal `${escaped}` in output
 34→///
 35→/// # Returns
 36→///
 37→/// Vec of segments representing the parsed string
 38→pub fn parse_interpolation(input: &str) -> Vec<Segment> {
 39→    let mut segments = Vec::new();
 40→    let mut chars = input.chars().peekable();
 41→    let mut current_literal = String::new();
 42→
 43→    while let Some(c) = chars.next() {
 44→        if c == '$' {
 45→            match chars.peek() {
 46→                Some('$') => {
 47→                    // Escaped: $$ becomes $
 48→                    chars.next();
 49→                    if chars.peek() == Some(&'{') {
 50→                        // $${...} -> literal ${...}
 51→                        chars.next(); // consume {
 52→                        current_literal.push('$');
 53→                        current_literal.push('{');
 54→                        // Read until closing brace
 55→                        while let Some(&c) = chars.peek() {
 56→                            chars.next();
 57→                            current_literal.push(c);
 58→                            if c == '}' {
 59→                                break;
 60→                            }
 61→                        }
 62→                    } else {
 63→                        current_literal.push('$');
 64→                    }
 65→                }
 66→                Some('{') => {
 67→                    // Start of variable
 68→                    chars.next(); // consume {
 69→
 70→                    // Flush current literal
 71→                    if !current_literal.is_empty() {
 72→                        segments.push(Segment::Literal(std::mem::take(&mut current_literal)));
 73→                    }
 74→
 75→                    // Read variable name until }
 76→                    let mut var_name = String::new();
 77→                    while let Some(&c) = chars.peek() {
 78→                        if c == '}' {
 79→                            chars.next();
 80→                            break;
 81→                        }
 82→                        var_name.push(chars.next().unwrap());
 83→                    }
 84→
 85→                    segments.push(Segment::Variable(var_name));
 86→                }
 87→                _ => {
 88→                    current_literal.push(c);
 89→                }
 90→            }
 91→        } else {
 92→            current_literal.push(c);
 93→        }
 94→    }
 95→
 96→    // Flush remaining literal
 97→    if !current_literal.is_empty() {
 98→        segments.push(Segment::Literal(current_literal));
 99→    }
100→
101→    segments
102→}
103→
104→/// Extract all variable names from an interpolated string.
105→///
106→/// Returns unique variable names found in the string.
107→pub fn extract_variables(input: &str) -> HashSet<String> {
108→    parse_interpolation(input)
109→        .into_iter()
110→        .filter_map(|seg| match seg {
111→            Segment::Variable(name) => Some(name),
112→            _ => None,
113→        })
114→        .collect()
115→}
116→
117→/// Check if a string contains any interpolation.
118→pub fn has_interpolation(input: &str) -> bool {
119→    parse_interpolation(input)
120→        .iter()
121→        .any(|seg| matches!(seg, Segment::Variable(_)))
122→}
123→
124→/// Context for variable resolution.
125→///
126→/// Variables are resolved in priority order:
127→/// 1. Prompt values from current run (highest priority)
128→/// 2. Saved preferences from previous runs
129→/// 3. User-defined variables from `vars:` config
130→/// 4. Environment variables
131→/// 5. Built-in variables (lowest priority)
132→#[derive(Debug, Default)]
133→pub struct InterpolationContext {
134→    /// Prompt values from current run
135→    pub prompts: HashMap<String, String>,
136→
137→    /// Saved preferences from previous runs
138→    pub preferences: HashMap<String, String>,
139→
140→    /// User-defined variables from `vars:` config
141→    pub vars: HashMap<String, String>,
142→
143→    /// Environment variables
144→    pub env: HashMap<String, String>,
145→
146→    /// Built-in variables (project_name, project_root, bivvy_version)
147→    pub builtins: HashMap<String, String>,
148→}
149→
150→impl InterpolationContext {

 1→//! Bivvy - Interactive development environment setup automation.
 2→//!
 3→//! Bivvy is a CLI tool that replaces ad-hoc `bin/setup` scripts with
 4→//! declarative YAML configuration and a polished interactive CLI experience.
 5→//!
 6→//! # Modules
 7→//!
 8→//! - [`cli`] - Command-line interface and argument parsing
 9→//! - [`config`] - Configuration loading, parsing, and validation
10→//! - [`environment`] - Environment detection and resolution
11→//! - [`error`] - Error types and result aliases
12→//! - [`lint`] - Configuration validation and linting
