"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.template_sources.len(), 1);
        assert_eq!(config.template_sources[0].priority, 10);
        assert_eq!(config.template_sources[0].timeout, 60);
    }

