        let config_path = temp.path().join("config.yml");
        fs::write(
            &config_path,
            r#"
app_name: "FullApp"
settings:
  default_output: quiet
steps:
  test:
    command: "echo test"
workflows:
  default:
    steps: [test]
"#,
        )
